#include <stdio.h>
int main(void) {
    /* DP stores answers to reusable subproblems. */
    int dp[6] = {0, 1, 1, 2, 3, 5};
    printf("%d\n", dp[5]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[] = {3, -2, 1, 3, 0};
    int take = a[0], skip = 0;
    for (int i = 1; i < 5; ++i) {
        int next = skip + a[i];
        skip = (skip > take ? skip : take);
        take = next;
    }
    printf("%d\n", skip > take ? skip : take);
    return 0;
}

